package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags this owner as a <em>possible</em> (soft) duplicate. A possible duplicate is a near match — some
 * other owner sharing this owner's last name (compared case-insensitively) and postcode — that is not a
 * suspected duplicate only because it was explicitly declared.
 *
 * <p>Because the household is now keyed on (lastName, postcode) (see {@link Household}), any other owner
 * sharing this owner's last name and postcode is in the <em>same household</em>. Such an owner can only
 * have been created by declaring {@code sharesHousehold} to bypass the household duplicate block
 * ({@link CheckHouseholdUnique}) — a non-declared one would have been rejected with a 409. A declared
 * household member is not a suspected duplicate, so this owner is left unflagged whenever a same-household
 * owner exists; otherwise there is no near match to flag.
 *
 * <p>Sets {@code possibleDuplicate} to {@code false} and {@code possibleDuplicateOf} to {@code null}
 * accordingly. Both are computed per request, not persisted, so the flag is recomputed identically on
 * each read. The step reads only the stored owner (no request body), so it runs unchanged on both the
 * create and read pipelines; the owner itself is excluded from the comparison by id.
 */
public class FlagPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        owner.setPossibleDuplicate(false);
        owner.setPossibleDuplicateOf(null);

        String lastName = owner.getLastName();
        String postcode = owner.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return;
        }

        for (Owner existing : ownerRepository.findAll()) {
            if (isSelf(owner, existing)) {
                continue;
            }
            if (equalsIgnoreCase(lastName, existing.getLastName())
                    && postcode.equals(existing.getPostcode())) {
                // Same last name and postcode means the same household. A same-household owner exists
                // only because sharesHousehold was declared, so this owner is a declared member, not a
                // suspected duplicate — leave it unflagged.
                return;
            }
        }
    }

    private static boolean isSelf(Owner owner, Owner existing) {
        return owner.getId() != null && owner.getId().equals(existing.getId());
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}
